// El dispositivo no tiene reloj de tiempo real y no sabe quién es
// dentro de la planta. Ese contexto se agrega aquí, en el borde.

let d = msg.payload;
if (typeof d === "string") {
    try { d = JSON.parse(d); } catch (e) { d = { crudo: d }; }
}

const partes = msg.topic.split("/");

msg.payload = {
    raiz:        partes[0] || null,
    equipo:      partes[1] || null,
    dispositivo: partes[2] || null,
    medida:      partes[3] || null,
    ...d,
    recibido_en: new Date().toISOString()
};

return msg;

const partes = msg.topic.split("/");
const quien = partes[1] + " / " + partes[2];
const vivo  = (msg.payload === "online");

node.status({
    fill: vivo ? "green" : "red",
    shape: "dot",
    text: quien + ": " + msg.payload
});

msg.payload = {
    dispositivo: quien,
    estado: msg.payload,
    retenido: msg.retain === true,
    visto_en: new Date().toISOString()
};

return msg;
